import{_ as t,o as a,c as l,a2 as i}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Πρώτη κράτηση: από προσφορά σε διακανονισμό","description":"","frontmatter":{},"headers":[],"relativePath":"el/getting-started/first-reservation.md","filePath":"el/getting-started/first-reservation.md"}'),r={name:"el/getting-started/first-reservation.md"};function s(o,e,n,c,p,d){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="πρωτη-κρατηση-απο-προσφορα-σε-διακανονισμο" tabindex="-1">Πρώτη κράτηση: από προσφορά σε διακανονισμό <a class="header-anchor" href="#πρωτη-κρατηση-απο-προσφορα-σε-διακανονισμο" aria-label="Permalink to &quot;Πρώτη κράτηση: από προσφορά σε διακανονισμό&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Οδηγίες βάσει v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, δικαιώματα και εγκεκριμένο εύρος. Η εκπαίδευση χρησιμοποιεί εγκεκριμένα συνθετικά δεδομένα· δεν εγκρίνεται εμπορική ενεργοποίηση.</p></div><h2 id="εκπαιδευτικο-σεναριο" tabindex="-1">Εκπαιδευτικό σενάριο <a class="header-anchor" href="#εκπαιδευτικο-σεναριο" aria-label="Permalink to &quot;Εκπαιδευτικό σενάριο&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένη συνθετική εταιρεία με τοποθεσίες, κατηγορία, ναύλο, οδηγό και όχημα. Επιλέξτε μελλοντική παραλαβή εντός δοκιμαστικού προγράμματος. Δεν απαιτούνται πραγματικά στοιχεία επιβάτη, εξωτερικά μηνύματα ή online χρεώσεις.</p><ol><li>Δημιουργήστε απλή κράτηση χειριστή. Επιλέξτε αγορά, έγκυρα σημεία, ημερομηνία/ώρα, επιβάτες, αποσκευές και κατηγορία. Εισαγάγετε συνθετικό όνομα και επιτρεπόμενο τηλέφωνο· αφήστε email κενό αν δεν δόθηκε.</li><li>Ελέγξτε προσφορά διακομιστή. Αν λείπει έγκυρος ναύλος, χρησιμοποιήστε χειροκίνητο έλεγχο. Μην επινοείτε ναύλο, έκπτωση ή email. Επιβεβαιώστε απαιτούμενα πεδία και υποβάλετε μία φορά.</li><li>Επαληθεύστε αναφορά, κατάσταση και τιμή. Σε αβέβαιη απόκριση αναζητήστε την κράτηση πριν την επανάληψη.</li><li>Αναθέστε μόνο μετά τους απαιτούμενους ελέγχους προσφοράς και κράτησης. Επιλέξτε κατάλληλο διαθέσιμο οδηγό και όχημα. Ελέγξτε πλήρες διάστημα, συγκρούσεις, χωρητικότητα και αποθηκευμένη ανάθεση.</li><li>Συνδεθείτε με εξουσιοδοτημένο συνθετικό λογαριασμό οδηγού. Ελέγξτε και προχωρήστε μόνο την ανατεθειμένη διαδρομή μέσω επιτρεπόμενων σταδίων. Η προσομοίωση διαχειριστή δεν αποδεικνύει πρόσβαση οδηγού.</li><li>Για δοκιμή μετρητών καταχωρίστε μόνο συνθετικό ποσό απόδειξης. Ελέγξτε υπόλοιπο, οδηγό είσπραξης και χωριστή παράδοση γραφείου. Δεν γίνεται πραγματική πληρωμή.</li><li>Ελέγξτε τελική κατάσταση, σύνδεση CRM, καθολικό και ιστορικό. Δοκιμάστε ειδοποιήσεις μόνο με προεπισκοπήσεις ή απομονωμένα εγκεκριμένα κανάλια.</li></ol><p>Επαναλάβετε με ανεξάρτητη ανάθεση επιστροφής και δοκιμάστε ωριαία υπηρεσία ή ιδιωτική εκδρομή αν προσφέρεται. Η ολοκλήρωση εκπαίδευσης δεν εγκρίνει πραγματική λειτουργία.</p><p>Δείτε <a href="/el/plus/create-reservation.html">Κράτηση</a>, <a href="/el/plus/dispatch-schedule.html">Αναθέσεις</a>, <a href="/el/plus/cash-management.html">Μετρητά</a> και <a href="/el/plus/customer-booking-gateway.html">Πύλη πελατών</a>.</p>',7)])])}const _=t(r,[["render",s]]);export{m as __pageData,_ as default};
